from pathlib import Path
root = Path(__file__).parent
checks = []
def check(name, ok): checks.append((name, bool(ok)))
service = (root/'src/medical-records/medical-records.service.ts').read_text()
controller = (root/'src/medical-records/medical-records.controller.ts').read_text()
public_controller = (root/'src/medical-records/medical-prescription-verification.controller.ts').read_text()
module = (root/'src/medical-records/medical-records.module.ts').read_text()
entity = (root/'src/medical-records/medical-prescription.entity.ts').read_text()
migration = (root/'src/database/migrations/1734500000000-AddPrescriptionVerificationTokens.ts').read_text()
package = (root/'package.json').read_text()
docs = (root/'docs/phase-v84-printable-prescriptions-and-verification.md').read_text()
env = (root/'.env.example').read_text()
check('print route is authenticated by protected medical records controller', "@Get('prescriptions/:recordId/print')" in controller and '@UseGuards(JwtAuthGuard, RolesGuard)' in controller)
check('print endpoint returns HTML with explicit content type', "@Header('Content-Type', 'text/html; charset=utf-8')" in controller)
check('print endpoint disables caching', "@Header('Cache-Control', 'private, no-store, max-age=0')" in controller)
check('print flow reuses existing access-checked prescription read', 'this.getPrescription(recordId, actor)' in service)
check('print flow requires approved issuing doctor', 'DoctorProfileStatus.APPROVED' in service and "بيانات الطبيب غير متاحة" in service)
check('print page includes doctor clinic identity', all(x in service for x in ['doctor.clinicName', 'doctor.fullName', 'doctor.specialty', 'doctor.address']))
check('print page renders all structured medication columns', all(x in service for x in ['medicationName', 'dosage', 'frequency', 'duration', 'instructions']))
check('dynamic HTML values are escaped', 'private escapeHtml' in service and "'&amp;'" in service and 'this.escapeHtml(m.medicationName)' in service)
check('QR code generated with qrcode dependency', 'QRCode.toDataURL' in service and '"qrcode":' in package)
check('verification token has 256-bit random entropy', "randomBytes(32).toString('hex')" in service)
check('verification token is not selected by default', 'select: false' in entity and 'verificationToken' in entity)
check('verification token is stable across repeated print requests', 'if (current.verificationToken) return current.verificationToken' in service)
check('token is stored under row lock', "lock: { mode: 'pessimistic_write' }" in service)
check('verification endpoint is public and isolated from guarded controller', '@Controller(\'medical-records/verify\')' in public_controller and '@UseGuards' not in public_controller)
check('verification route validates token format', "! /^[a-f0-9]{64}$/i.test(token)" not in service and "!/^[a-f0-9]{64}$/i.test(token)" in service)
check('verification response excludes patient and prescription contents', 'privacy:' in service and 'patientUserId' not in service[service.index('async verifyPrescriptionToken'):])
check('verification response checks non-deleted source record', 'deletedAt: IsNull()' in service[service.index('async verifyPrescriptionToken'):])
check('verification reports expired prescriptions', "status: expired ? 'expired' : 'valid'" in service)
check('verification endpoint disables caching and content sniffing', "@Header('Cache-Control', 'no-store, max-age=0')" in public_controller and "@Header('X-Content-Type-Options', 'nosniff')" in public_controller)
check('public verification controller registered in module', 'MedicalPrescriptionVerificationController' in module)
check('migration adds verification token column and unique partial index', '"verificationToken" varchar(64)' in migration and 'uq_medical_prescriptions_verification_token' in migration)
check('migration rollback removes index and column', 'DROP INDEX' in migration and 'DROP COLUMN "verificationToken"' in migration)
check('public API base URL documented in environment template', 'PUBLIC_API_BASE_URL=' in env)
check('docs explain browser print/save PDF workflow', 'طباعة' in service and 'Save as PDF' in docs)
check('docs explicitly state server-signed PDF is not included', 'not a server-generated signed PDF' in docs)
check('docs define both API routes and migration', 'GET /api/v1/medical-records/prescriptions/:recordId/print' in docs and '1734500000000' in docs)
check('migration file is included in TypeORM migrations glob', "migrations:['src/database/migrations/*.ts']" in (root/'src/database/data-source.ts').read_text())
check('no automatic TypeORM synchronize enabled', 'synchronize:false' in (root/'src/database/data-source.ts').read_text())
for name, ok in checks:
    print(('PASS' if ok else 'FAIL') + ' ' + name)
print(f'RESULT {sum(ok for _, ok in checks)}/{len(checks)}')
raise SystemExit(0 if all(ok for _, ok in checks) else 1)
